INSERT INTO disclosure_config_version (jurisdiction, transaction_type, use_class, version, items, status, note) VALUES
  ('NSW', 'sale', 'residential', 1, '[{"key":"nsw_planning_certificate","label":"Section 10.7 planning certificate","description":"A current planning certificate for the property, showing zoning and the planning controls that apply. It is attached to the contract for sale.","legalRef":"Environmental Planning and Assessment Act 1979 (NSW), s 10.7; Conveyancing (Sale of Land) Regulation 2022 (NSW), Sch 1","notApplicableAllowed":false},{"key":"nsw_title_document","label":"Title documents","description":"A current title search or the registered title for the property, attached to the contract for sale.","legalRef":"Conveyancing Act 1919 (NSW), s 52A; Conveyancing (Sale of Land) Regulation 2022 (NSW), Sch 1","notApplicableAllowed":false},{"key":"nsw_sewer_diagram","label":"Sewer service diagram","description":"The Sydney Water (or local water authority) sewer service diagram showing the sewer lines on the property.","legalRef":"Conveyancing (Sale of Land) Regulation 2022 (NSW), Sch 1","notApplicableAllowed":false},{"key":"nsw_strata_information","label":"Strata information certificate","description":"For a lot in a strata scheme: the strata information certificate (levies, by-laws, insurance, sinking fund and other prescribed details). Mark not applicable if the lot is not in a strata scheme.","legalRef":"Strata Schemes Management Act 2015 (NSW), s 184; Conveyancing (Sale of Land) Regulation 2022 (NSW), Sch 1","propertyTypes":["unit","townhouse","other"],"notApplicableAllowed":true},{"key":"nsw_pool_compliance","label":"Swimming pool certificate or exemption","description":"If there is a swimming pool: a current certificate of compliance or occupation certificate, or the registration details. Mark not applicable if there is no pool.","legalRef":"Swimming Pools Act 1992 (NSW), Pt 2; Conveyancing (Sale of Land) Regulation 2022 (NSW), Sch 1","propertyTypes":["house","unit","townhouse","other"],"notApplicableAllowed":true}]'::jsonb, 'draft', 'Draft by engineering from public sources on 6 Nov 2026. Compliance and counsel must confirm items, section numbers and wording before approving.'),
  ('VIC', 'sale', 'residential', 1, '[{"key":"vic_section_32","label":"Section 32 vendor statement","description":"The signed vendor statement given to buyers before they sign a contract. It covers title, mortgages and encumbrances, planning controls and overlays (including any heritage overlay), rates and charges, and notices or orders on the property.","legalRef":"Sale of Land Act 1962 (Vic), s 32","notApplicableAllowed":false},{"key":"vic_building_permits","label":"Building permits and occupancy certificate","description":"Building permits issued in the last 7 years, with the certificate of occupancy or final inspection certificate, and any owner-builder insurance details.","legalRef":"Sale of Land Act 1962 (Vic), s 32; Building Act 1993 (Vic)","notApplicableAllowed":false},{"key":"vic_owners_corporation","label":"Owners corporation certificate","description":"For a lot in an owners corporation: the current owners corporation certificate (fees, special levies, insurance and rules). Mark not applicable if the lot is not in an owners corporation.","legalRef":"Owners Corporations Act 2006 (Vic), s 151; Sale of Land Act 1962 (Vic), s 32","propertyTypes":["unit","townhouse","other"],"notApplicableAllowed":true}]'::jsonb, 'draft', 'Draft by engineering from public sources on 6 Nov 2026. Compliance and counsel must confirm items, section numbers and wording before approving.'),
  ('SA', 'sale', 'residential', 1, '[{"key":"sa_form_1_vendor_statement","label":"Form 1 vendor''s statement","description":"The vendor''s statement (Form 1) given to the buyer before the contract is signed, with the attached council, water and sewerage and other prescribed information.","legalRef":"Land and Business (Sale and Conveyancing) Act 1994 (SA), s 7","notApplicableAllowed":false},{"key":"sa_title_search","label":"Certificate of title search","description":"A current certificate of title search, attached to the Form 1 vendor''s statement.","legalRef":"Land and Business (Sale and Conveyancing) Act 1994 (SA), s 7","notApplicableAllowed":false},{"key":"sa_community_title","label":"Community or strata title information","description":"For a lot in a community or strata scheme: the by-laws, levies and insurance details required with the Form 1 statement. Mark not applicable if the lot is not in a scheme.","legalRef":"Land and Business (Sale and Conveyancing) Act 1994 (SA), s 7; Community Titles Act 1996 (SA)","propertyTypes":["unit","townhouse","other"],"notApplicableAllowed":true}]'::jsonb, 'draft', 'Draft by engineering from public sources on 6 Nov 2026. Compliance and counsel must confirm items, section numbers and wording before approving.'),
  ('WA', 'sale', 'residential', 1, '[{"key":"wa_title_search","label":"Certificate of title search","description":"A current certificate of title search showing the registered owner, easements, caveats and other interests.","legalRef":"Transfer of Land Act 1893 (WA)","notApplicableAllowed":false},{"key":"wa_strata_information","label":"Strata information for the buyer","description":"For a strata lot: the information a seller must give a buyer before the contract (levies, by-laws, insurance and the scheme''s financial position). Mark not applicable if the lot is not in a strata scheme.","legalRef":"Strata Titles Act 1985 (WA), seller''s information to a buyer","propertyTypes":["unit","townhouse","other"],"notApplicableAllowed":true}]'::jsonb, 'draft', 'Draft by engineering from public sources on 6 Nov 2026. Compliance and counsel must confirm items, section numbers and wording before approving.'),
  ('TAS', 'sale', 'residential', 1, '[{"key":"tas_vendor_disclosure","label":"Vendor disclosure statement","description":"The vendor''s disclosure of title details, easements and covenants, planning and building matters, rates and any notices affecting the property, given to the buyer before they are bound.","legalRef":"Land Titles Act 1980 (Tas), s 35","notApplicableAllowed":false},{"key":"tas_title_documents","label":"Title folio and plan","description":"A current copy of the folio of the Register and the title plan for the property.","legalRef":"Land Titles Act 1980 (Tas)","notApplicableAllowed":false}]'::jsonb, 'draft', 'Draft by engineering from public sources on 6 Nov 2026. Compliance and counsel must confirm items, section numbers and wording before approving.'),
  ('ACT', 'sale', 'residential', 1, '[{"key":"act_sale_disclosure","label":"Contract disclosure statement","description":"The statement of prescribed information (title, lease, rates, encumbrances and notices) that must accompany the contract for sale of residential property in the ACT.","legalRef":"Civil Law (Sale of Residential Property) Act 2003 (ACT)","notApplicableAllowed":false},{"key":"act_building_report","label":"Building inspection report","description":"A building inspection report for the property, provided with the contract.","legalRef":"Civil Law (Sale of Residential Property) Act 2003 (ACT)","notApplicableAllowed":false},{"key":"act_pest_report","label":"Pest inspection report","description":"A pest inspection report for the property, provided with the contract.","legalRef":"Civil Law (Sale of Residential Property) Act 2003 (ACT)","notApplicableAllowed":false},{"key":"act_energy_rating","label":"Energy efficiency rating statement","description":"The energy efficiency rating statement for the dwelling, disclosed in advertising and the contract.","legalRef":"Civil Law (Sale of Residential Property) Act 2003 (ACT); Energy Efficiency Rating legislation (ACT)","propertyTypes":["house","unit","townhouse"],"notApplicableAllowed":false},{"key":"act_unit_title_certificate","label":"Unit title certificate","description":"For a unit: the unit title certificate (levies, rules, sinking fund and insurance). Mark not applicable if the property is not a unit.","legalRef":"Unit Titles (Management) Act 2011 (ACT)","propertyTypes":["unit","townhouse","other"],"notApplicableAllowed":true}]'::jsonb, 'draft', 'Draft by engineering from public sources on 6 Nov 2026. Compliance and counsel must confirm items, section numbers and wording before approving.'),
  ('NT', 'sale', 'residential', 1, '[{"key":"nt_vendor_disclosure","label":"Vendor disclosure statement","description":"The vendor''s statement of title, encumbrances, planning, rates and other prescribed matters, given to the buyer before the contract is signed.","legalRef":"Law of Property Act 2000 (NT), vendor disclosure requirements","notApplicableAllowed":false},{"key":"nt_title_search","label":"Title search","description":"A current title search for the property.","legalRef":"Land Title Act 2000 (NT)","notApplicableAllowed":false},{"key":"nt_unit_title","label":"Unit title information","description":"For a unit: the body corporate statement of levies, rules and insurance. Mark not applicable if the property is not a unit.","legalRef":"Unit Titles Act 1975 (NT)","propertyTypes":["unit","townhouse","other"],"notApplicableAllowed":true}]'::jsonb, 'draft', 'Draft by engineering from public sources on 6 Nov 2026. Compliance and counsel must confirm items, section numbers and wording before approving.');
